package com.campusevents.service;
import com.campusevents.dao.UserDAO;import com.campusevents.model.User;import com.campusevents.util.PasswordUtil;
public class AuthService {private final UserDAO dao=new UserDAO();public User login(String email,String password)throws Exception{User u=dao.login(email.trim());if(u==null||!PasswordUtil.verify(password,u.getPasswordHash()))throw new Exception("Invalid email or password.");return u;}public void register(String name,String email,String pass,String college,String dept,int year,String phone)throws Exception{if(name.isBlank()||email.isBlank()||college.isBlank()||dept.isBlank()||phone.isBlank())throw new Exception("All fields are required.");if(pass.length()<8)throw new Exception("Password must be at least 8 characters.");dao.register(name,email,PasswordUtil.hash(pass),college,dept,year,phone);}}
